import { useState } from 'react';
import Button from 'react-bootstrap/Button';
import Modal from 'react-bootstrap/Modal';
import Col from 'react-bootstrap/Col';
import Form from 'react-bootstrap/Form';
import { InputGroup } from 'react-bootstrap/InputGroup';
import { Row } from 'react-bootstrap/Row';
import '../styles/ProfileModal.css';

function ProfileModal() {

  // Modal setup
  const [show, setShow] = useState(false);
  const handleClose = () => setShow(false);
  const handleShow = () => setShow(true);


  // Input validation
  const [validated, setValidated] = useState(false);
  const handleSubmit = (event) => {
    const form = event.currentTarget;
    if (form.checkValidity() === false) {
      event.preventDefault();
      event.stopPropagation();
    }
    setValidated(true);
  };


  // Profile modal
  return (
    <>
      <Button className="rounded-pill mt-5 profile-modal-button" variant="primary" onClick={handleShow}>Edit</Button>

      <Modal centered size='lg' show={show} onHide={handleClose}>
        <Modal.Header closeButton>
          <Modal.Title id="contained-modal-title-vcenter">Edit Profile</Modal.Title>
        </Modal.Header>

        <Modal.Body>






        </Modal.Body>

        <Modal.Footer>
          <Button variant="secondary" className="rounded-pill" onClick={handleClose}>
            Cancel
          </Button>
          <Button variant="success" onClick={handleClose} className="rounded-pill">
            Submit
          </Button>
        </Modal.Footer>
      </Modal>
    </>
  );
}

export default ProfileModal;
